CREATE TEMP TABLE fork_selected_executions AS SELECT execution_id FROM item_catalog WHERE item_id IN (SELECT item_id FROM fork_selected_items) AND execution_id IS NOT NULL UNION SELECT execution_id FROM context_assemblies WHERE assembly_id IN (SELECT assembly_id FROM fork_selected_assemblies) UNION SELECT snapshot.execution_id FROM resource_activation_snapshots snapshot JOIN fork_selected_activations selected ON selected.session_id=snapshot.session_id AND selected.thread_id=snapshot.thread_id AND selected.activation_snapshot_id=snapshot.activation_snapshot_id UNION SELECT initial_execution_id FROM turn_records WHERE turn_id IN (SELECT turn_id FROM fork_selected_turns) UNION SELECT last_execution_id FROM turn_records WHERE turn_id IN (SELECT turn_id FROM fork_selected_turns) AND last_execution_id IS NOT NULL
